    svg: '<svg viewBox="0 0 400 232" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><rect x="10" y="110" width="380" height="120" class="fw"/><rect x="58" y="111" width="44" height="56" class="fl"/><polygon points="100,146 222,176 222,202 100,166" class="fl"/><rect x="222" y="111" width="96" height="92" class="fl"/><polygon points="246,202 254,172 264,188 274,164 284,188 294,176 298,202" class="fd"/><rect x="236" y="194" width="68" height="8" rx="4" class="fl" transform="rotate(0 270 198)"/><circle cx="226" cy="105" r="8" class="fl"/><circle cx="314" cy="105" r="8" class="fl"/><rect x="214" y="52" width="112" height="46" rx="8" class="fl"/><line x1="214" y1="66" x2="326" y2="66" class="thin"/><line x1="14" y1="94" x2="43.2" y2="94" class="ln"/><polygon points="52,94 41,100 41,88" class="solid-t"/><line x1="108" y1="152" x2="205.5" y2="175.9" class="la"/><polygon points="214,178 201.9,181.2 204.7,169.6" class="solid-a"/><text x="14" y="80" class="s">Wind</text><text x="80" y="98" class="s" text-anchor="middle">Air hole</text><text x="270" y="40" class="s" text-anchor="middle">Pot on rocks</text><text x="270" y="222" class="s" text-anchor="middle">Fire hole</text><line x1="270" y1="208" x2="270" y2="204" class="thin"/><text x="150" y="214" class="s" text-anchor="middle">Slanting tunnel</text><line x1="150" y1="200" x2="150" y2="184" class="thin"/><text x="14" y="222" class="s">Windward side</text></svg>'
